<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__);require $root.'/global/connection.php';require_once $root.'/global/inventory-document.php';
$pdo->beginTransaction();
try{
 $suffix=substr(bin2hex(random_bytes(5)),0,10);$warehouse=(int)$pdo->query('SELECT id FROM tbl_warehouse WHERE active_status=1 ORDER BY id LIMIT 1')->fetchColumn();$user=(int)$pdo->query('SELECT id FROM tbl_user ORDER BY id LIMIT 1')->fetchColumn();
 $pdo->prepare("INSERT INTO tbl_product(code,barcode,sunat_item_code,brand,name,description,stock_quantity,unit_price,unit_value,sunat_unit_code,tax_affectation_code,osce_catalog_code,manufacturer_code,model,active_status) VALUES(?,?,?,?,?,?,0,0,'UND','NIU','10','','','',1)")->execute(['QA-ID-'.$suffix,'QA-ID-'.$suffix,'','QA','Artículo documento inventario '.$suffix,'QA']);$product=(int)$pdo->lastInsertId();
 $entry=app_inventory_document_create($pdo,['document_type'=>'ENTRY','warehouse_id'=>$warehouse,'document_date'=>date('Y-m-d'),'reason'=>'Ingreso de prueba','lines'=>[['product_id'=>$product,'quantity'=>10,'unit_cost'=>5]]],$user);
 $stock=$pdo->query("SELECT quantity,inventory_value,average_unit_cost FROM tbl_warehouse_stock WHERE warehouse_id={$warehouse} AND product_id={$product}")->fetch();if(abs((float)$stock['quantity']-10)>0.001||abs((float)$stock['inventory_value']-50)>0.01||abs((float)$stock['average_unit_cost']-5)>0.001)throw new RuntimeException('La entrada no valorizó correctamente el inventario.');
 $issue=app_inventory_document_create($pdo,['document_type'=>'ISSUE','warehouse_id'=>$warehouse,'document_date'=>date('Y-m-d'),'reason'=>'Consumo interno QA','lines'=>[['product_id'=>$product,'quantity'=>3]]],$user);
 $stock=$pdo->query("SELECT quantity,inventory_value FROM tbl_warehouse_stock WHERE warehouse_id={$warehouse} AND product_id={$product}")->fetch();if(abs((float)$stock['quantity']-7)>0.001||abs((float)$stock['inventory_value']-35)>0.01)throw new RuntimeException('La salida no consumió cantidad y valor correctamente.');
 $pdo->exec('SAVEPOINT before_overissue');try{app_inventory_document_create($pdo,['document_type'=>'ISSUE','warehouse_id'=>$warehouse,'document_date'=>date('Y-m-d'),'reason'=>'Salida excesiva QA','lines'=>[['product_id'=>$product,'quantity'=>99]]],$user);throw new RuntimeException('Se permitió una salida superior al disponible.');}catch(DomainException $expected){}$pdo->exec('ROLLBACK TO SAVEPOINT before_overissue');
 try{app_inventory_document_cancel($pdo,$entry['id'],'Intento con salida activa',$user);throw new RuntimeException('Se anuló una entrada con salida posterior activa.');}catch(DomainException $expected){}
 app_inventory_document_cancel($pdo,$issue['id'],'Reversión de salida QA',$user);$stock=$pdo->query("SELECT quantity,inventory_value FROM tbl_warehouse_stock WHERE warehouse_id={$warehouse} AND product_id={$product}")->fetch();if(abs((float)$stock['quantity']-10)>0.001||abs((float)$stock['inventory_value']-50)>0.01)throw new RuntimeException('La anulación de salida no restauró el inventario.');
 app_inventory_document_cancel($pdo,$entry['id'],'Reversión de entrada QA',$user);$stock=$pdo->query("SELECT quantity,inventory_value FROM tbl_warehouse_stock WHERE warehouse_id={$warehouse} AND product_id={$product}")->fetch();if(abs((float)$stock['quantity'])>0.001||abs((float)$stock['inventory_value'])>0.01)throw new RuntimeException('La anulación de entrada no restauró el inventario.');
 $pdo->rollBack();echo "PASS inventory entry issue valuation protection and reversal lifecycle\n";
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,$e->getMessage()."\n");exit(1);}
